     $pack$[{"key":"1","parent_key":null,"label":"Cover Letter and Request Statement","mandatory":true,"path_order":1},{"key":"2","parent_key":null,"label":"Product Description and Proposed Indication","mandatory":true,"path_order":2},{"key":"3","parent_key":null,"label":"Serious or Life-Threatening Condition Justification","mandatory":true,"path_order":3},{"key":"4","parent_key":null,"label":"Available Therapy","mandatory":true,"path_order":4},{"key":"5","parent_key":null,"label":"Significant Improvement in Safety or Effectiveness","mandatory":true,"path_order":5},{"key":"6","parent_key":null,"label":"Location of the Supporting Data in the Application","mandatory":false,"path_order":6}]$pack$::jsonb,
