  FOR e IN SELECT * FROM jsonb_array_elements(expected) LOOP
    tree := CASE (e->>'doc_type') || ':' || (e->>'agency') || ':' || (e->>'version')
    WHEN 'priority_review:fda:fda-priority-review-request-v1.0' THEN $pack$[{"key":"1","parent_key":null,"label":"Cover Letter and Request Statement","mandatory":true,"path_order":1},{"key":"2","parent_key":null,"label":"Product Description and Proposed Indication","mandatory":true,"path_order":2},{"key":"3","parent_key":null,"label":"Serious or Life-Threatening Condition Justification","mandatory":true,"path_order":3},{"key":"4","parent_key":null,"label":"Available Therapy","mandatory":true,"path_order":4},{"key":"5","parent_key":null,"label":"Significant Improvement in Safety or Effectiveness","mandatory":true,"path_order":5},{"key":"6","parent_key":null,"label":"Location of the Supporting Data in the Application","mandatory":false,"path_order":6}]$pack$::jsonb
    WHEN 'environmental_assessment:fda:fda-environmental-assessment-v1.0' THEN $pack$[{"key":"EA.1","parent_key":null,"label":"Date and Applicant","mandatory":true,"path_order":1},{"key":"EA.2","parent_key":null,"label":"Description of the Proposed Action and Need","mandatory":true,"path_order":2},{"key":"EA.3","parent_key":null,"label":"Substances Introduced into the Environment","mandatory":true,"path_order":3},{"key":"EA.4","parent_key":null,"label":"Fate and Environmental Effects of Released Substances","mandatory":true,"path_order":4},{"key":"EA.5","parent_key":null,"label":"Use of Resources and Energy","mandatory":false,"path_order":5},{"key":"EA.6","parent_key":null,"label":"Mitigation Measures","mandatory":true,"path_order":6},{"key":"EA.7","parent_key":null,"label":"Alternatives to the Proposed Action","mandatory":true,"path_order":7},{"key":"EA.8","parent_key":null,"label":"List of Preparers, Certification, and References","mandatory":true,"path_order":8}]$pack$::jsonb
    WHEN 'icsr_15day:fda:fda-icsr-15day-v1.0' THEN $pack$[{"key":"C.1","parent_key":null,"label":"Case Administrative Information (Safety Report ID, Dates)","mandatory":true,"path_order":1},{"key":"D","parent_key":null,"label":"Patient Characteristics","mandatory":true,"path_order":2},{"key":"G","parent_key":null,"label":"Suspect / Concomitant Drug Information","mandatory":true,"path_order":3},{"key":"E","parent_key":null,"label":"Reaction / Event (MedDRA Coded)","mandatory":true,"path_order":4},{"key":"E.i.3","parent_key":null,"label":"Seriousness and Outcome","mandatory":true,"path_order":5},{"key":"H.1","parent_key":null,"label":"Case Narrative","mandatory":true,"path_order":6},{"key":"H.5","parent_key":null,"label":"Causality (Reporter / Company Assessment)","mandatory":true,"path_order":7},{"key":"C.2","parent_key":null,"label":"Primary Source / Reporter Information","mandatory":true,"path_order":8}]$pack$::jsonb
    END;
    SELECT jsonb_array_length(required_sections), required_sections = tree, superseded_by
      INTO n, same, sup
      FROM c2c_rule_packs
     WHERE doc_type = e->>'doc_type' AND agency = e->>'agency' AND version = e->>'version';
    IF NOT FOUND OR n IS DISTINCT FROM (e->>'nodes')::integer OR same IS NOT TRUE THEN
      RAISE EXCEPTION '%:% % must hold this file''s % nodes; found % (tree matches: %)',
        e->>'doc_type', e->>'agency', e->>'version', e->>'nodes',
        coalesce(n::text, 'no row'), coalesce(same::text, 'n/a');
    END IF;
    IF sup IS NOT NULL AND NOT EXISTS (
      SELECT 1 FROM c2c_rule_packs
       WHERE doc_type = e->>'doc_type' AND agency = e->>'agency' AND version = sup) THEN
      RAISE EXCEPTION '%:% % is superseded by %, which does not exist',
